const references = `## Official references and further reading

- [Ghana Public Procurement Authority](https://ppa.gov.gh/) — legislation, manuals, circulars and standard tender documents.
- [BidScope Ghana tenders](/tenders/ghana) — organised opportunity discovery, alerts and procurement-intelligence workflow.

For a live external tender, use the official-source link shown on its BidScope record to verify the controlling documents and amendments. This article is operational guidance, not legal advice.`;

function body(article: EditorialArticle) {
  return `# ${article.title}

${article.opening}

## The strategic question

${article.thesis}

${article.sections.map(([heading, copy]) => `## ${heading}\n\n${copy}`).join("\n\n")}

## Practical operating checklist

${article.checklist.map((item) => `- ${item}`).join("\n")}

## The BidScope perspective

${article.decision}

## Questions decision-makers should ask

### What evidence would change our decision?

Name the missing fact, document or commercial assumption before committing resources. A disciplined team separates what it knows from what it merely hopes is true.

### Who owns the next action?

Every qualified opportunity needs one accountable owner, a dated next action and an internal deadline earlier than the buyer's deadline. Without those controls, an opportunity is only a bookmark.

${references}`;
}

